use std::time::Duration;

use rmcp::{
    model::{ClientJsonRpcMessage, ClientRequest, PingRequest, RequestId},
    transport::streamable_http_server::session::{SessionManager, local::LocalSessionManager},
};

#[tokio::test]
async fn test_init_timeout_terminates_pre_init_session() -> anyhow::Result<()> {
    let mut manager = LocalSessionManager::default();
    manager.session_config.init_timeout = Some(Duration::from_millis(200));

    // Bind the transport so its drop-guard doesn't cancel the worker — we
    // want termination via init_timeout, not via cancellation.
    let (session_id, _transport) = manager.create_session().await?;

    tokio::time::sleep(Duration::from_millis(500)).await;

    let message = ClientJsonRpcMessage::request(
        ClientRequest::PingRequest(PingRequest::default()),
        RequestId::Number(1),
    );
    let result = manager.initialize_session(&session_id, message).await;

    assert!(
        result.is_err(),
        "expected worker to be dead; got: {result:?}"
    );

    Ok(())
}

#[tokio::test]
async fn test_init_timeout_none_keeps_worker_alive() -> anyhow::Result<()> {
    let mut manager = LocalSessionManager::default();
    manager.session_config.init_timeout = None;

    let (session_id, _transport) = manager.create_session().await?;

    tokio::time::sleep(Duration::from_millis(500)).await;

    let message = ClientJsonRpcMessage::request(
        ClientRequest::PingRequest(PingRequest::default()),
        RequestId::Number(1),
    );
    // Liveness probe: a live worker accepts the send then stalls waiting for
    // a handler response (none is wired up), tripping the outer timeout. A
    // dead worker would fail the send and return immediately.
    let probe = tokio::time::timeout(
        Duration::from_millis(200),
        manager.initialize_session(&session_id, message),
    )
    .await;

    assert!(
        probe.is_err(),
        "expected worker to be alive; got: {probe:?}"
    );

    Ok(())
}

use std::{any::Any, time::Duration};

use rmcp::task_manager::{
    OperationDescriptor, OperationMessage, OperationProcessor, OperationResultTransport,
};

struct DummyTransport {
    id: String,
    value: u32,
}

impl OperationResultTransport for DummyTransport {
    fn operation_id(&self) -> &String {
        &self.id
    }

    fn as_any(&self) -> &dyn Any {
        self
    }
}

#[tokio::test]
async fn executes_enqueued_future() {
    let mut processor = OperationProcessor::new();
    let descriptor = OperationDescriptor::new("op1", "dummy");
    let future = Box::pin(async {
        tokio::time::sleep(Duration::from_millis(10)).await;
        Ok(Box::new(DummyTransport {
            id: "op1".to_string(),
            value: 42,
        }) as Box<dyn OperationResultTransport>)
    });

    processor
        .submit_operation(OperationMessage::new(descriptor, future))
        .expect("submit operation");

    tokio::time::sleep(Duration::from_millis(30)).await;
    let results = processor.peek_completed();
    assert_eq!(results.len(), 1);
    let payload = results[0]
        .result
        .as_ref()
        .unwrap()
        .as_any()
        .downcast_ref::<DummyTransport>()
        .unwrap();
    assert_eq!(payload.value, 42);
}

#[tokio::test]
async fn rejects_duplicate_operation_ids() {
    let mut processor = OperationProcessor::new();
    let descriptor = OperationDescriptor::new("dup", "dummy");
    let future = Box::pin(async {
        Ok(Box::new(DummyTransport {
            id: "dup".to_string(),
            value: 1,
        }) as Box<dyn OperationResultTransport>)
    });
    processor
        .submit_operation(OperationMessage::new(descriptor, future))
        .expect("first submit");

    let descriptor_dup = OperationDescriptor::new("dup", "dummy");
    let future_dup = Box::pin(async {
        Ok(Box::new(DummyTransport {
            id: "dup".to_string(),
            value: 2,
        }) as Box<dyn OperationResultTransport>)
    });

    let err = processor
        .submit_operation(OperationMessage::new(descriptor_dup, future_dup))
        .expect_err("duplicate should fail");
    assert!(format!("{err}").contains("already running"));
}
